    private void thenV2PinIsCreated() {
        assertNotNull(this.v2Pin);
        assertTrue(this.v2Pin instanceof LibGpiodV2Pin);
    }

    private void thenV2PinHasCorrectParameters(String pinName, int pinTerminal, KuraGPIODirection direction,
            KuraGPIOMode mode, KuraGPIOTrigger trigger) {
        assertEquals(pinName, this.v2Pin.getName());
        assertEquals(pinTerminal, this.v2Pin.getIndex());
        assertEquals(direction, this.v2Pin.getDirection());
        assertEquals(mode, this.v2Pin.getMode());
        assertEquals(trigger, this.v2Pin.getTrigger());
    }

    private void thenV2PinIsNotOpen() {
        assertFalse(v2Pin.isOpen());
    }

    private void thenV2PinIsOpen() {
        assertTrue(v2Pin.isOpen());
    }

    private void thenV2PinValueIsBoolean() {
        assertNotNull(this.v2PinValue);
        assertTrue(this.v2PinValue instanceof Boolean);
    }

    private void thenV2PinValueReadIs(boolean expectedValue) {
        assertEquals(expectedValue, this.v2PinValue);
    }

    private void thenV2PinIndexIs(int expectedIndex) {
        assertEquals(expectedIndex, this.v2Pin.getIndex());
    }

    private void thenMessageIs(String expectedMessage) {
        assertEquals(expectedMessage, this.message);
    }
    
    private void thenListenerIsInvokedAtLeastTimes(int times) {
        verify(this.pinStatusListener, atLeast(times)).pinStatusChange(anyBoolean());
    }

